/**
 * Params of `toolchain.resolve`.
 */
export type ToolchainResolveParams = { component: ToolComponent, 
/**
 * The project root, for `[toolchain]` and `[debug] lldb`.
 */
project?: string, };

/**
 * Params of `toolchain.uninstall`.
 */
export type ToolchainUninstallParams = { component: ManagedComponent, version: string, };

/**
 * Result of `toolchain.uninstall`.
 */
export type ToolchainUninstallResult = { freedBytes: number, };

/**
 * The daemon's own log levels (tracing's, not Apple's `LogLevel`).
 */
export type TraceLevel = "trace" | "debug" | "info" | "warn" | "error";

/**
 * `yes`, `no` or `unknown`.
 */
export type Tristate = "yes" | "no" | "unknown";

/**
 * Tunnel states.
 */
export type TunnelState = "down" | "up" | "failed";

/**
 * The userspace tunnel to the device.
 */
export type TunnelStatus = { state: TunnelState, generation?: number, 
/**
 * RFC 3339 UTC.
 */
since?: string, 
/**
 * Only when `state` is `failed`.
 */
error?: ErrorData, };

/**
 * Params of `ui.confirm` (served by `cli` with a TTY or `--yes`, and `ide`).
 */
export type UiConfirmParams = { title: string, message: string, detail?: string, 
/**
 * Destructive: the client shows it as dangerous.
 */
danger: boolean, requestedBy: ClientRef, 
/**
 * Unanswered after this long counts as declined.
 */
timeoutMs: number, };

/**
 * Result of `ui.confirm`.
 */
export type UiConfirmResult = { confirmed: boolean, };

/**
 * Params of `ui.openUrl`.
 */
export type UiOpenUrlParams = { url: string, reason: string, };

/**
 * Result of `ui.openUrl`.
 */
export type UiOpenUrlResult = { opened: boolean, };

/**
 * Params of `ui.prompt` (`cli` and `ide` only).
 */
export type UiPromptParams = { title: string, message: string, kind: PromptKind, 
/**
 * Do not echo; never sent to `mcp`.
 */
secret: boolean, 
/**
 * For `typed-confirmation`: the text to type.
 */
expected?: string, requestedBy: ClientRef, timeoutMs: number, };

/**
 * Result of `ui.prompt`. `Debug` never prints the value (it may be a password).
 */
export type UiPromptResult = { value?: string, cancelled: boolean, };

/**
 * Params of the `ui.showMessage` notification (to the target client).
 */
export type UiShowMessageParams = { level: MessageLevel, message: string, actions?: Array<string>, };

/**
 * Placeholder DTO of a method whose shape is not written yet (freeze F0): any JSON object, unknown fields
 * ignored. The owning area replaces its `…Params`/`…Result` aliases with real structs.
 */
export type Unspecified = Record<symbol, never>;

/**
 * A variable in DAP shape (`debug.inspect what: variables`, `debug.evaluate`).
 */
export type Variable = { name: string, value: string, type?: string, 
/**
 * Non-zero when the variable can be expanded further (a DAP `variablesReference`).
 */
variablesReference?: number, };

/**
 * One verified bundle.
 */
export type VerifiedBundle = { relPath: string, bundleId?: string, identifier?: string, cdhash?: string, 
/**
 * Masked.
 */
teamId?: string, profileUuid?: string, signed: boolean, };

/**
 * The value of `$/progress` (ARCHITECTURE §7.6): LSP work-done progress plus Russet's `jobId`.
 */
export type WorkDoneProgress = { kind: ProgressKind, title?: string, message?: string, 
/**
 * 0–100.
 */
percentage?: number, cancellable?: boolean, 
/**
 * The job behind the request, on `begin` (ARCHITECTURE §7.6).
 */
jobId?: JobId, };

/**
 * `initialize.params.workspace`.
 */
export type Workspace = { 
/**
 * Absolute project roots.
 */
roots: Array<string>, };

